#include <vector>
#include <string>
#include <cstddef>
#include <omp.h>

struct Book {
    std::string title;
    int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    const size_t n = books.size();
    size_t result = n; // sentinel for "not found"

    #pragma omp parallel
    {
        size_t localBest = n;

        #pragma omp for nowait
        for (size_t i = 0; i < n; ++i) {
            if (books[i].pages < 100) {
                if (localBest == n || i > localBest) localBest = i;
            }
        }

        #pragma omp critical
        {
            if (localBest != n && (result == n || localBest > result)) {
                result = localBest;
            }
        }
    }

    return result;
}
